8: /** The base URL for the OpenMRS REST API (e.g., '/ws/rest/v1'). */
9: export const restBaseUrl = '/ws/rest/v1';
10: /** The base URL for the OpenMRS FHIR R4 API (e.g., '/ws/fhir2/R4'). */
11: export const fhirBaseUrl = '/ws/fhir2/R4';
12: /** The endpoint for session management operations. */
