15: /**
16:  * Append `path` to the OpenMRS SPA base.
17:  *
18:  * @param path The path to append to the OpenMRS base URL.
19:  * @returns The full URL with the OpenMRS base prepended. If the path is already
20:  *   an absolute URL (starting with 'http'), it is returned unchanged.
21:  *
22:  * @example
23:  *
24:  * ```ts
25:  * makeUrl('/foo/bar');
26:  * // => '/openmrs/foo/bar'
27:  * ```
28:  */
29: export function makeUrl(path: string) {
30:   if (path && path.startsWith('http')) {
31:     return path;
32:   } else if (path[0] !== '/') {
33:     // ensure path starts with /
34:     path = '/' + path;
35:   }
36: 
37:   return window.openmrsBase + path;
38: }
